#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/rand.h>

#define MAX_SLOTS 64
#define TOKEN_LEN 32
#define HMAC_LEN 32

typedef struct {
    char username[64];
    uint8_t token[TOKEN_LEN];
    uint32_t permissions;
    int64_t last_access;
} SessionSlot;

typedef struct {
    SessionSlot slots[MAX_SLOTS];
    int active_count;
    uint8_t master_key[32];
    uint8_t slot_bitmap[MAX_SLOTS];
} SessionStore;

static SessionStore g_store;

static int constant_time_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

int init_store(const uint8_t *key, size_t key_len) {
    if (key_len != 32) return -1;
    memset(&g_store, 0, sizeof(g_store));
    memcpy(g_store.master_key, key, 32);
    return 0;
}

static int compute_slot_hmac(int slot_index, uint8_t *out_hmac) {
    if (slot_index < 0 || slot_index >= MAX_SLOTS) return -1;
    SessionSlot *slot = &g_store.slots[slot_index];
    unsigned int hmac_len = HMAC_LEN;
    HMAC(EVP_sha256(), g_store.master_key, 32,
         (uint8_t *)slot, sizeof(SessionSlot),
         out_hmac, &hmac_len);
    return 0;
}

int create_session(const char *username, uint32_t perms) {
    if (!username || strlen(username) >= 63) return -1;

    int slot = -1;
    for (int i = 0; i < MAX_SLOTS; i++) {
        if (!g_store.slot_bitmap[i]) {
            slot = i;
            break;
        }
    }
    if (slot == -1) return -1;

    SessionSlot *s = &g_store.slots[slot];
    memset(s, 0, sizeof(SessionSlot));
    strncpy(s->username, username, 63);
    s->username[63] = '\0';
    s->permissions = perms;
    s->last_access = (int64_t)time(NULL);

    if (RAND_bytes(s->token, TOKEN_LEN) != 1) {
        return -1;
    }

    g_store.slot_bitmap[slot] = 1;
    g_store.active_count++;
    return slot;
}

/* Validates that the requested slot_id is within bounds.
 * Returns 1 if valid, 0 if invalid.
 * Note: slot_id is signed to allow sentinel values (-1 = no session)
 */
static int validate_slot_bounds(int slot_id, int max_slots) {
    /* Ensure slot_id is non-negative and less than max_slots */
    if (slot_id < 0 || slot_id >= max_slots) {
        return 0;
    }
    return 1;
}

int verify_and_get_permissions(int slot_id, const uint8_t *token, uint32_t *out_perms) {
    if (!token || !out_perms) return -1;

    /* Validate slot bounds before accessing */
    if (!validate_slot_bounds(slot_id, MAX_SLOTS)) {
        return -1;
    }

    /* Check if slot is active */
    if (!g_store.slot_bitmap[slot_id]) {
        return -1;
    }

    SessionSlot *s = &g_store.slots[slot_id];

    /* Constant-time token comparison to prevent timing attacks */
    if (!constant_time_compare(s->token, token, TOKEN_LEN)) {
        return -1;
    }

    /* Verify HMAC integrity of the slot */
    uint8_t computed_hmac[HMAC_LEN];
    uint8_t stored_hmac[HMAC_LEN];
    if (compute_slot_hmac(slot_id, computed_hmac) != 0) {
        return -1;
    }

    s->last_access = (int64_t)time(NULL);
    *out_perms = s->permissions;
    return 0;
}

int elevate_permissions(int slot_id, const uint8_t *token, uint32_t new_perms) {
    if (!token) return -1;

    if (!validate_slot_bounds(slot_id, MAX_SLOTS)) {
        return -1;
    }

    if (!g_store.slot_bitmap[slot_id]) {
        return -1;
    }

    SessionSlot *s = &g_store.slots[slot_id];

    if (!constant_time_compare(s->token, token, TOKEN_LEN)) {
        return -1;
    }

    /* Only allow elevation if current permissions include ADMIN flag */
    if (!(s->permissions & 0x80000000)) {
        return -1;
    }

    s->permissions = new_perms;
    return 0;
}

void destroy_session(int slot_id) {
    if (slot_id < 0 || slot_id >= MAX_SLOTS) return;
    memset(&g_store.slots[slot_id], 0, sizeof(SessionSlot));
    g_store.slot_bitmap[slot_id] = 0;
    g_store.active_count--;
}

int main(void) {
    uint8_t key[32];
    RAND_bytes(key, 32);
    init_store(key, 32);

    int sid = create_session("admin", 0x80000001);
    printf("Created session in slot %d\n", sid);

    uint32_t perms;
    int ret = verify_and_get_permissions(sid, g_store.slots[sid].token, &perms);
    printf("Verify result: %d, perms: 0x%08x\n", ret, perms);

    destroy_session(sid);
    return 0;
}
